import torch

def f1(x: torch.Tensor, dim: int, factor: int) -> torch.Tensor:
    input_size = x.size()
    scale_divisor = int(factor ** dim)
    output_size = [input_size[0], input_size[1] // scale_divisor]
    output_size += [d * factor for d in input_size[2:]]
    return x.reshape(output_size)

def f2(x: torch.Tensor, dim: int, factor: int) -> torch.Tensor:
    input_size = x.size()
    scale_divisor = 1
    for _ in range(dim):
        scale_divisor *= factor
    output_size = [input_size[0], input_size[1] // scale_divisor]
    output_size += [d * factor for d in input_size[2:]]
    return x.reshape(output_size)

for f in (f1, f2):
